export {};

const handlers = new Map<string, Function>();
const dispatch = jest.fn();
const powerListeners = new Map<string, Function>();

jest.mock('../../ipc/main', () => ({
  handle: (channel: string, fn: Function) => {
    handlers.set(channel, fn);
  },
}));

jest.mock('../../store', () => ({
  dispatch: (...args: any[]) => dispatch(...args),
}));

jest.mock('electron', () => ({
  powerMonitor: {
    addListener: (event: string, fn: Function) => {
      powerListeners.set(event, fn);
    },
    getSystemIdleState: jest.fn(() => 'active'),
  },
}));

describe('userPresence/main setupPowerMonitor', () => {
  beforeEach(() => {
    jest.clearAllMocks();
    handlers.clear();
    powerListeners.clear();
    jest.resetModules();
    // eslint-disable-next-line @typescript-eslint/no-var-requires
    require('../main').setupPowerMonitor();
  });

  it('registers power monitor listeners and idle-state handler', async () => {
    expect(powerListeners.has('suspend')).toBe(true);
    expect(powerListeners.has('lock-screen')).toBe(true);
    expect(handlers.has('power-monitor/get-system-idle-state')).toBe(true);

    powerListeners.get('suspend')?.();
    powerListeners.get('lock-screen')?.();
    expect(dispatch).toHaveBeenCalledTimes(2);

    const state = await handlers.get('power-monitor/get-system-idle-state')?.(
      {},
      60
    );
    expect(state).toBe('active');
  });
});

import fs from 'fs';

import { ABOUT_DIALOG_UPDATE_CHANNEL_CHANGED } from '../../ui/actions';
// eslint-disable-next-line import/order
import {
  UPDATE_SKIPPED,
  UPDATES_CHECK_FOR_UPDATES_REQUESTED,
  UPDATES_INSTALL_REQUESTED,
  UPDATES_SKIP_REQUESTED,
} from '../actions';

const listeners = new Map<string, Function>();
const select = jest.fn();
const dispatch = jest.fn();
// Mirrors electron-updater: the constructor allows prereleases when the
// running version has a prerelease id, and the `channel` setter always
// turns `allowDowngrade` on.
const autoUpdater = {
  logger: null as unknown,
  autoDownload: false,
  allowPrerelease: true,
  allowDowngrade: false,
  _channel: null as string | null,
  get channel(): string | null {
    return this._channel;
  },
  set channel(value: string | null) {
    this._channel = value;
    this.allowDowngrade = true;
  },
  checkForUpdates: jest.fn(async () => undefined),
  checkForUpdatesAndNotify: jest.fn(async () => undefined),
  quitAndInstall: jest.fn(),
  downloadUpdate: jest.fn(async () => undefined),
  on: jest.fn(),
  once: jest.fn(),
  addListener: jest.fn(),
  removeListener: jest.fn(),
  removeAllListeners: jest.fn(),
  updateConfigPath: '',
};

jest.mock('fs', () => ({
  promises: {
    readFile: jest.fn(async () => '{}'),
  },
}));

jest.mock('electron', () => ({
  app: {
    getAppPath: jest.fn(() => '/app'),
    getPath: jest.fn(() => '/userData'),
    isPackaged: true,
  },
  BrowserWindow: {
    getAllWindows: jest.fn(() => []),
    getFocusedWindow: jest.fn(() => null),
  },
  autoUpdater: {
    on: jest.fn(),
  },
}));

jest.mock('electron-updater', () => ({
  autoUpdater,
}));

jest.mock('../../store', () => ({
  select: (...args: unknown[]) => select(...args),
  dispatch: (...args: unknown[]) => dispatch(...args),
  listen: (type: string, fn: Function) => {
    listeners.set(type, fn);
    return () => listeners.delete(type);
  },
}));

jest.mock('../../ui/main/dialogs', () => ({
  askUpdateInstall: jest.fn(async () => 0),
  AskUpdateInstallResponse: { INSTALL_UPDATE_AND_RESTART: 0 },
  warnAboutInstallUpdateLater: jest.fn(),
  warnAboutUpdateDownload: jest.fn(),
  warnAboutUpdateSkipped: jest.fn(),
}));

// Must stay below the `autoUpdater` const and jest.mock('electron-updater', ...)
// above: importing '../main' pulls in electron-updater, whose mock factory
// closes over `autoUpdater` — hoisting this import breaks that initialization order.
// eslint-disable-next-line import/first
import { setupUpdates } from '../main';

describe('updates/setupUpdates', () => {
  // `isUpdatingAllowed` is computed by the real loadConfiguration() selector
  // straight from process.platform/process.mas/process.windowsStore — never
  // from the mocked store state — so it varies by CI runner OS unless pinned
  // here. Force the win32-without-windowsStore branch deterministically.
  const originalPlatform = process.platform;
  const originalWindowsStore = process.windowsStore;

  beforeEach(() => {
    jest.clearAllMocks();
    listeners.clear();
    Object.defineProperty(process, 'platform', {
      value: 'win32',
      configurable: true,
    });
    Object.defineProperty(process, 'windowsStore', {
      value: false,
      configurable: true,
    });
    select.mockImplementation((selector: any) =>
      selector({
        isUpdatingEnabled: true,
        doCheckForUpdatesOnStartup: false,
        skippedUpdateVersion: null,
        isReportEnabled: true,
        isFlashFrameEnabled: true,
        isHardwareAccelerationEnabled: true,
        isInternalVideoChatWindowEnabled: true,
        isVideoCallScreenCaptureFallbackEnabled: false,
        updateChannel: 'latest',
        isEachUpdatesSettingConfigurable: true,
        isUpdatingAllowed: true,
        newUpdateVersion: null,
      })
    );
    (fs.promises.readFile as jest.Mock).mockResolvedValue('{}');
    autoUpdater.allowPrerelease = true;
    autoUpdater.allowDowngrade = false;
    autoUpdater._channel = null;
  });

  afterEach(() => {
    Object.defineProperty(process, 'platform', {
      value: originalPlatform,
      configurable: true,
    });
    Object.defineProperty(process, 'windowsStore', {
      value: originalWindowsStore,
      configurable: true,
    });
  });

  it('wires autoUpdater and action listeners', async () => {
    await setupUpdates();
    // electron-updater may use on() and/or addListener()
    expect(
      (autoUpdater.on as jest.Mock).mock.calls.length +
        (autoUpdater.addListener as jest.Mock).mock.calls.length
    ).toBeGreaterThan(0);
    expect(listeners.has(UPDATES_CHECK_FOR_UPDATES_REQUESTED)).toBe(true);
    expect(listeners.has(UPDATES_SKIP_REQUESTED)).toBe(true);
    expect(listeners.has(UPDATES_INSTALL_REQUESTED)).toBe(true);
    expect(listeners.has(ABOUT_DIALOG_UPDATE_CHANNEL_CHANGED)).toBe(true);
  });

  it('checks for updates when requested', async () => {
    await setupUpdates();
    await listeners.get(UPDATES_CHECK_FOR_UPDATES_REQUESTED)?.({
      type: UPDATES_CHECK_FOR_UPDATES_REQUESTED,
    });
    expect(autoUpdater.checkForUpdates).toHaveBeenCalled();
  });

  it('dispatches UPDATE_SKIPPED when skip dialog action fires', async () => {
    await setupUpdates();
    await listeners.get(UPDATES_SKIP_REQUESTED)?.({
      type: UPDATES_SKIP_REQUESTED,
      payload: '9.9.9',
    });
    expect(dispatch).toHaveBeenCalledWith(
      expect.objectContaining({
        type: UPDATE_SKIPPED,
        payload: '9.9.9',
      })
    );
  });

  it('loads update.json configuration files', async () => {
    await setupUpdates();
    expect(fs.promises.readFile).toHaveBeenCalled();
  });

  describe('update channel', () => {
    const withChannel = (updateChannel: string) =>
      select.mockImplementation((selector: any) =>
        selector({
          isUpdatingEnabled: true,
          doCheckForUpdatesOnStartup: false,
          skippedUpdateVersion: null,
          updateChannel,
          isEachUpdatesSettingConfigurable: true,
          isUpdatingAllowed: true,
          newUpdateVersion: null,
        })
      );

    it('turns prereleases and downgrades off on the stable channel', async () => {
      withChannel('latest');
      await setupUpdates();
      expect(autoUpdater.channel).toBe('latest');
      expect(autoUpdater.allowPrerelease).toBe(false);
      expect(autoUpdater.allowDowngrade).toBe(false);
    });

    it.each(['alpha', 'beta'])(
      'allows prereleases but no downgrades on the %s channel',
      async (channel) => {
        withChannel(channel);
        await setupUpdates();
        expect(autoUpdater.channel).toBe(channel);
        expect(autoUpdater.allowPrerelease).toBe(true);
        expect(autoUpdater.allowDowngrade).toBe(false);
      }
    );

    it('keeps the same rules when the user changes the channel', async () => {
      withChannel('alpha');
      await setupUpdates();

      await listeners.get(ABOUT_DIALOG_UPDATE_CHANNEL_CHANGED)?.({
        type: ABOUT_DIALOG_UPDATE_CHANNEL_CHANGED,
        payload: 'latest',
      });
      expect(autoUpdater.channel).toBe('latest');
      expect(autoUpdater.allowPrerelease).toBe(false);
      expect(autoUpdater.allowDowngrade).toBe(false);

      await listeners.get(ABOUT_DIALOG_UPDATE_CHANNEL_CHANGED)?.({
        type: ABOUT_DIALOG_UPDATE_CHANNEL_CHANGED,
        payload: 'beta',
      });
      expect(autoUpdater.channel).toBe('beta');
      expect(autoUpdater.allowPrerelease).toBe(true);
      expect(autoUpdater.allowDowngrade).toBe(false);
    });
  });
});

import type { ActionOf } from '../../store/actions';
import {
  DOWNLOAD_CREATED,
  DOWNLOAD_REMOVED,
  DOWNLOAD_UPDATED,
  DOWNLOADS_CLEARED,
} from '../actions';
import type { Download } from '../common';
import { DownloadStatus } from '../common';

describe('download actions', () => {
  const mockDownload: Download = {
    itemId: 1640995200000,
    state: 'progressing',
    status: DownloadStatus.ALL,
    fileName: 'test-file.pdf',
    receivedBytes: 1024,
    totalBytes: 2048,
    startTime: 1640995200000,
    endTime: undefined,
    url: 'https://example.com/file.pdf',
    serverUrl: 'https://open.rocket.chat',
    serverTitle: 'Rocket.Chat Community',
    mimeType: 'application/pdf',
    savePath: '/downloads/test-file.pdf',
  };

  describe('action constants', () => {
    it('should have correct action type constants', () => {
      expect(DOWNLOAD_CREATED).toBe('downloads/created');
      expect(DOWNLOAD_UPDATED).toBe('downloads/updated');
      expect(DOWNLOAD_REMOVED).toBe('downloads/removed');
      expect(DOWNLOADS_CLEARED).toBe('downloads/cleared');
    });
  });

  describe('action creators', () => {
    describe('DOWNLOAD_CREATED action', () => {
      it('should create a valid DOWNLOAD_CREATED action', () => {
        const action: ActionOf<typeof DOWNLOAD_CREATED> = {
          type: DOWNLOAD_CREATED,
          payload: mockDownload,
        };

        expect(action.type).toBe(DOWNLOAD_CREATED);
        expect(action.payload).toEqual(mockDownload);
      });

      it('should work with different download states', () => {
        const pausedDownload: Download = {
          ...mockDownload,
          state: 'paused',
          status: DownloadStatus.PAUSED,
        };

        const action: ActionOf<typeof DOWNLOAD_CREATED> = {
          type: DOWNLOAD_CREATED,
          payload: pausedDownload,
        };

        expect(action.payload.state).toBe('paused');
        expect(action.payload.status).toBe(DownloadStatus.PAUSED);
      });
    });

    describe('DOWNLOAD_UPDATED action', () => {
      it('should create a valid DOWNLOAD_UPDATED action with complete payload', () => {
        const updatePayload = {
          itemId: mockDownload.itemId,
          state: 'completed' as const,
          status: DownloadStatus.ALL,
          fileName: 'test-file.pdf',
          receivedBytes: 2048,
          totalBytes: 2048,
          startTime: 1640995200000,
          endTime: 1640995400000,
          url: 'https://example.com/file.pdf',
          mimeType: 'application/pdf',
          savePath: '/downloads/test-file.pdf',
        };

        const action: ActionOf<typeof DOWNLOAD_UPDATED> = {
          type: DOWNLOAD_UPDATED,
          payload: updatePayload,
        };

        expect(action.type).toBe(DOWNLOAD_UPDATED);
        expect(action.payload).toEqual(updatePayload);
      });

      it('should create a valid DOWNLOAD_UPDATED action with partial payload', () => {
        const partialUpdatePayload = {
          itemId: mockDownload.itemId,
          receivedBytes: 1536,
          endTime: 1640995300000,
        };

        const action: ActionOf<typeof DOWNLOAD_UPDATED> = {
          type: DOWNLOAD_UPDATED,
          payload: partialUpdatePayload,
        };

        expect(action.type).toBe(DOWNLOAD_UPDATED);
        expect(action.payload.itemId).toBe(mockDownload.itemId);
        expect(action.payload.receivedBytes).toBe(1536);
        expect(action.payload.endTime).toBe(1640995300000);
      });

      it('should handle different download states in updates', () => {
        const cancelledUpdatePayload = {
          itemId: mockDownload.itemId,
          state: 'cancelled' as const,
          status: DownloadStatus.CANCELLED,
          endTime: 1640995400000,
        };

        const action: ActionOf<typeof DOWNLOAD_UPDATED> = {
          type: DOWNLOAD_UPDATED,
          payload: cancelledUpdatePayload,
        };

        expect(action.payload.state).toBe('cancelled');
        expect(action.payload.status).toBe(DownloadStatus.CANCELLED);
      });
    });

    describe('DOWNLOAD_REMOVED action', () => {
      it('should create a valid DOWNLOAD_REMOVED action', () => {
        const action: ActionOf<typeof DOWNLOAD_REMOVED> = {
          type: DOWNLOAD_REMOVED,
          payload: mockDownload.itemId,
        };

        expect(action.type).toBe(DOWNLOAD_REMOVED);
        expect(action.payload).toBe(mockDownload.itemId);
      });

      it('should work with different itemId types', () => {
        const numericItemId = 1640995200000;
        const action: ActionOf<typeof DOWNLOAD_REMOVED> = {
          type: DOWNLOAD_REMOVED,
          payload: numericItemId,
        };

        expect(action.payload).toBe(numericItemId);
        expect(typeof action.payload).toBe('number');
      });
    });

    describe('DOWNLOADS_CLEARED action', () => {
      it('should create a valid DOWNLOADS_CLEARED action', () => {
        const action: ActionOf<typeof DOWNLOADS_CLEARED> = {
          type: DOWNLOADS_CLEARED,
        };

        expect(action.type).toBe(DOWNLOADS_CLEARED);
        expect('payload' in action).toBe(false);
      });
    });
  });

  describe('action type guards', () => {
    it('should correctly identify DOWNLOAD_CREATED actions', () => {
      const action: ActionOf<typeof DOWNLOAD_CREATED> = {
        type: DOWNLOAD_CREATED,
        payload: mockDownload,
      };

      expect(action.type === DOWNLOAD_CREATED).toBe(true);
    });

    it('should correctly identify DOWNLOAD_UPDATED actions', () => {
      const action: ActionOf<typeof DOWNLOAD_UPDATED> = {
        type: DOWNLOAD_UPDATED,
        payload: {
          itemId: mockDownload.itemId,
          receivedBytes: 1536,
        },
      };

      expect(action.type === DOWNLOAD_UPDATED).toBe(true);
    });

    it('should correctly identify DOWNLOAD_REMOVED actions', () => {
      const action: ActionOf<typeof DOWNLOAD_REMOVED> = {
        type: DOWNLOAD_REMOVED,
        payload: mockDownload.itemId,
      };

      expect(action.type === DOWNLOAD_REMOVED).toBe(true);
    });

    it('should correctly identify DOWNLOADS_CLEARED actions', () => {
      const action: ActionOf<typeof DOWNLOADS_CLEARED> = {
        type: DOWNLOADS_CLEARED,
      };

      expect(action.type === DOWNLOADS_CLEARED).toBe(true);
    });
  });

  describe('payload validation', () => {
    it('should require valid Download object for DOWNLOAD_CREATED', () => {
      // This is a compile-time test, but we can verify the structure
      const action: ActionOf<typeof DOWNLOAD_CREATED> = {
        type: DOWNLOAD_CREATED,
        payload: mockDownload,
      };

      // All required fields should be present
      expect(action.payload.itemId).toBeDefined();
      expect(action.payload.state).toBeDefined();
      expect(action.payload.status).toBeDefined();
      expect(action.payload.fileName).toBeDefined();
      expect(action.payload.receivedBytes).toBeDefined();
      expect(action.payload.totalBytes).toBeDefined();
      expect(action.payload.startTime).toBeDefined();
      expect(action.payload.url).toBeDefined();
      expect(action.payload.serverUrl).toBeDefined();
      expect(action.payload.serverTitle).toBeDefined();
      expect(action.payload.mimeType).toBeDefined();
      expect(action.payload.savePath).toBeDefined();
    });

    it('should allow partial Download object for DOWNLOAD_UPDATED', () => {
      const action: ActionOf<typeof DOWNLOAD_UPDATED> = {
        type: DOWNLOAD_UPDATED,
        payload: {
          itemId: mockDownload.itemId,
          // Only some fields - this should be valid
          receivedBytes: 1500,
          state: 'progressing',
        },
      };

      expect(action.payload.itemId).toBe(mockDownload.itemId);
      expect(action.payload.receivedBytes).toBe(1500);
      expect(action.payload.state).toBe('progressing');
    });
  });

  describe('immutability', () => {
    it('should not modify the original download object when creating actions', () => {
      const originalDownload = { ...mockDownload };

      const action: ActionOf<typeof DOWNLOAD_CREATED> = {
        type: DOWNLOAD_CREATED,
        payload: mockDownload,
      };

      // Modify the action payload
      action.payload.receivedBytes = 9999;

      // Original should be unchanged
      expect(originalDownload.receivedBytes).toBe(1024);
    });
  });
});

import {
