  SERVER_URL_RESOLVED,
} from '../actions';

const listenHandlers = new Map<string | Function, Function>();
const dispatch = jest.fn();
const select = jest.fn();
const invoke = jest.fn();
const getWebContentsByServerUrl = jest.fn();

jest.mock('fs', () => {
