describe('setupServers', () => {
  beforeEach(() => {
    jest.clearAllMocks();
    listenHandlers.clear();
    select.mockImplementation((sel: any) =>
      sel({
        servers: [
          {
            url: 'https://open.rocket.chat',
            title: 'Community',
            gitCommitHash: 'abc',
          },
        ],
        currentView: { url: 'https://open.rocket.chat' },
      })
    );
    invoke.mockResolvedValue(['https://open.rocket.chat/', '6.5.0']);
    getWebContentsByServerUrl.mockReturnValue({
      session: {
        clearStorageData: jest.fn(async () => undefined),
        clearCache: jest.fn(async () => undefined),
      },
      reload: jest.fn(),
    });
    jest.resetModules();
  });

  it('registers listeners and loads hosts from localStorage string', async () => {
    // eslint-disable-next-line @typescript-eslint/no-var-requires
    const { setupServers } = require('../main');
    await setupServers({
      'rocket.chat.hosts': JSON.stringify('https://extra.rocket.chat'),
      'rocket.chat.currentHost': 'https://extra.rocket.chat',
    });

    expect(listenHandlers.size).toBeGreaterThan(0);
    expect(dispatch).toHaveBeenCalled();
  });

  it('loads hosts from localStorage array JSON', async () => {
    // eslint-disable-next-line @typescript-eslint/no-var-requires
    const { setupServers } = require('../main');
    await setupServers({
      'rocket.chat.hosts': JSON.stringify(
        JSON.stringify(['https://a.example/', 'https://b.example/'])
      ),
    });
    expect(dispatch).toHaveBeenCalled();
  });

  it('loads app servers when map empty', async () => {
    select.mockImplementation((sel: any) =>
      sel({
        servers: [],
        currentView: 'add-new-server',
      })
    );
    // eslint-disable-next-line @typescript-eslint/no-var-requires
    const freshFs = require('fs');
    (freshFs.promises.readFile as jest.Mock).mockResolvedValueOnce(
      JSON.stringify({ Community: 'https://open.rocket.chat' })
    );
    // eslint-disable-next-line @typescript-eslint/no-var-requires
    const { setupServers } = require('../main');
    await setupServers({});
    expect(dispatch).toHaveBeenCalledWith(
      expect.objectContaining({
        payload: expect.objectContaining({
          servers: [{ url: 'https://open.rocket.chat', title: 'Community' }],
        }),
      })
    );
  });

  it('handles SERVER_URL_RESOLUTION_REQUESTED with meta', async () => {
    // eslint-disable-next-line @typescript-eslint/no-var-requires
    const { setupServers } = require('../main');
    await setupServers({});

    const handler = listenHandlers.get(SERVER_URL_RESOLUTION_REQUESTED);
    expect(handler).toBeDefined();

    await handler?.({
      type: SERVER_URL_RESOLUTION_REQUESTED,
      payload: 'https://open.rocket.chat',
      meta: { id: '1', response: false },
    });

    expect(dispatch).toHaveBeenCalledWith({
      type: SERVER_URL_RESOLVED,
      payload: ['https://open.rocket.chat/', 'ok'],
      meta: { response: true, id: '1' },
    });
  });

  it('handles git commit hash change by clearing guest storage', async () => {
    // eslint-disable-next-line @typescript-eslint/no-var-requires
    const { setupServers } = require('../main');
    await setupServers({});

    const handler = listenHandlers.get(WEBVIEW_GIT_COMMIT_HASH_CHECK);
    expect(handler).toBeDefined();

    const session = getWebContentsByServerUrl();
    await handler?.({
      type: WEBVIEW_GIT_COMMIT_HASH_CHECK,
      payload: {
        url: 'https://open.rocket.chat',
        gitCommitHash: 'def',
      },
    });

    expect(dispatch).toHaveBeenCalledWith({
      type: WEBVIEW_GIT_COMMIT_HASH_CHANGED,
      payload: { url: 'https://open.rocket.chat', gitCommitHash: 'def' },
    });
    expect(getWebContentsByServerUrl).toHaveBeenCalledWith(
      'https://open.rocket.chat'
    );
    expect(session.session.clearStorageData).toHaveBeenCalledWith({
      storages: ['indexdb'],
    });
    expect(session.session.clearCache).toHaveBeenCalled();
    expect(session.reload).toHaveBeenCalled();
  });

  it('ignores malformed hosts JSON', async () => {
    // eslint-disable-next-line @typescript-eslint/no-var-requires
    const { setupServers } = require('../main');
    await setupServers({
      'rocket.chat.hosts': '{not-json',
    });
    expect(dispatch).toHaveBeenCalled();
  });
});

import { checkScreenRecordingPermission } from '../screenRecordingPermission';

const getMediaAccessStatusMock = jest.fn();

jest.mock('electron', () => ({
  systemPreferences: {
    getMediaAccessStatus: (...args: unknown[]) =>
      getMediaAccessStatusMock(...args),
  },
}));

const setProcessPlatform = (platform: NodeJS.Platform): void => {
  Object.defineProperty(process, 'platform', {
    value: platform,
    configurable: true,
  });
};

describe('screenSharing/screenRecordingPermission', () => {
  afterEach(() => {
    setProcessPlatform('darwin');
    getMediaAccessStatusMock.mockReset();
  });

  it('returns true on darwin when screen access is granted', async () => {
    setProcessPlatform('darwin');
    getMediaAccessStatusMock.mockReturnValue('granted');

    await expect(checkScreenRecordingPermission()).resolves.toBe(true);
    expect(getMediaAccessStatusMock).toHaveBeenCalledWith('screen');
  });

  it('returns false on darwin when screen access is not granted', async () => {
    setProcessPlatform('darwin');
    getMediaAccessStatusMock.mockReturnValue('denied');

    await expect(checkScreenRecordingPermission()).resolves.toBe(false);
  });

  it('returns true on non-darwin platforms without querying media permissions', async () => {
    setProcessPlatform('linux');

    await expect(checkScreenRecordingPermission()).resolves.toBe(true);
    expect(getMediaAccessStatusMock).not.toHaveBeenCalled();
  });
});

import { handleMediaPermissionRequest } from '../mediaPermissions';

const getMediaAccessStatusMock = jest.fn();
const askForMediaAccessMock = jest.fn();
const shellOpenExternalMock = jest.fn();
const askForMediaPermissionSettingsMock = jest.fn();

const setProcessPlatform = (value: NodeJS.Platform): void => {
  Object.defineProperty(process, 'platform', {
    value,
    configurable: true,
  });
};

const resetPlatform = (): void => {
  setProcessPlatform('darwin');
};

jest.mock('electron', () => ({
  systemPreferences: {
    getMediaAccessStatus: (...args: any[]) => getMediaAccessStatusMock(...args),
    askForMediaAccess: (...args: any[]) => askForMediaAccessMock(...args),
  },
  shell: {
    openExternal: (...args: any[]) => shellOpenExternalMock(...args),
  },
}));

jest.mock('../dialogs', () => ({
  askForMediaPermissionSettings: (...args: any[]) =>
    askForMediaPermissionSettingsMock(...args),
}));

beforeEach(() => {
  resetPlatform();
  jest.clearAllMocks();
});

afterEach(() => {
  resetPlatform();
});

describe('ui/main/mediaPermissions', () => {
  it('allows media access on macOS when both statuses are granted', async () => {
    setProcessPlatform('darwin');
    getMediaAccessStatusMock
      .mockReturnValueOnce('granted')
      .mockReturnValueOnce('granted');

    const callback = jest.fn();

    await handleMediaPermissionRequest(
      ['audio', 'video'],
      null,
      'initiateCall',
      callback
    );

    expect(callback).toHaveBeenCalledWith(true);
    expect(askForMediaPermissionSettingsMock).not.toHaveBeenCalled();
    expect(shellOpenExternalMock).not.toHaveBeenCalled();
    expect(askForMediaAccessMock).not.toHaveBeenCalled();
  });

  it('opens macOS media settings when microphone and camera are denied', async () => {
    setProcessPlatform('darwin');
    const parentWindow = { isDestroyed: jest.fn(() => false), show: jest.fn() };
    getMediaAccessStatusMock
      .mockReturnValueOnce('denied')
      .mockReturnValueOnce('denied');
    askForMediaPermissionSettingsMock.mockResolvedValue(true);

    const callback = jest.fn();

    await handleMediaPermissionRequest(
      ['audio', 'video'],
      parentWindow as any,
      'answerCall',
      callback
    );

    expect(askForMediaPermissionSettingsMock).toHaveBeenCalledWith(
      'both',
      parentWindow
    );
    expect(shellOpenExternalMock).toHaveBeenCalledWith(
      'x-apple.systempreferences:com.apple.preference.security?Privacy_Microphone'
    );
    expect(callback).toHaveBeenCalledWith(false);
  });

  it('asks for access when media status is not-determined on macOS', async () => {
    setProcessPlatform('darwin');
    getMediaAccessStatusMock.mockReturnValueOnce('not-determined');
    askForMediaAccessMock.mockResolvedValue(true);

    const callback = jest.fn();

    await handleMediaPermissionRequest(
      ['audio'],
      null,
      'recordMessage',
      callback
    );

    expect(askForMediaAccessMock).toHaveBeenCalledWith('microphone');
    expect(callback).toHaveBeenCalledWith(true);
  });

  it('asks for access when video status is not-determined on macOS', async () => {
    setProcessPlatform('darwin');
    getMediaAccessStatusMock.mockReturnValueOnce('not-determined');
    askForMediaAccessMock.mockResolvedValue(true);

    const callback = jest.fn();

    await handleMediaPermissionRequest(
      ['video'],
      null,
      'recordMessage',
      callback
    );

    expect(askForMediaAccessMock).toHaveBeenCalledWith('camera');
    expect(callback).toHaveBeenCalledWith(true);
  });

  it('opens microphone settings when only microphone is denied', async () => {
    setProcessPlatform('darwin');
    const parentWindow = { isDestroyed: jest.fn(() => false), show: jest.fn() };
    getMediaAccessStatusMock.mockReturnValueOnce('denied');
    askForMediaPermissionSettingsMock.mockResolvedValue(true);

    const callback = jest.fn();

    await handleMediaPermissionRequest(
      ['audio'],
      parentWindow as any,
      'answerCall',
      callback
    );

    expect(askForMediaPermissionSettingsMock).toHaveBeenCalledWith(
      'microphone',
      parentWindow
    );
    expect(shellOpenExternalMock).toHaveBeenCalledWith(
      'x-apple.systempreferences:com.apple.preference.security?Privacy_Microphone'
    );
    expect(callback).toHaveBeenCalledWith(false);
  });

  it('logs when opening macOS media settings throws', async () => {
    setProcessPlatform('darwin');
    getMediaAccessStatusMock.mockReturnValueOnce('denied');
    askForMediaPermissionSettingsMock.mockRejectedValue(
      new Error('settings unavailable')
    );
    const parentWindow = { isDestroyed: jest.fn(() => false), show: jest.fn() };

    const warnMock = jest.spyOn(console, 'warn').mockImplementation(() => {});
    const callback = jest.fn();

    await handleMediaPermissionRequest(
      ['audio'],
      parentWindow as any,
      'initiateCall',
      callback
    );

    expect(warnMock).toHaveBeenCalledWith(
      'Failed to open media permission settings dialog:',
      expect.any(Error)
    );
    expect(callback).toHaveBeenCalledWith(false);
    warnMock.mockRestore();
  });

  it('opens Windows media settings when camera permission is denied', async () => {
    setProcessPlatform('win32');
    getMediaAccessStatusMock.mockReturnValueOnce('denied');
    const parentWindow = { isDestroyed: jest.fn(() => false), show: jest.fn() };
    askForMediaPermissionSettingsMock.mockResolvedValue(true);

    const callback = jest.fn();

    await handleMediaPermissionRequest(
      ['video'],
      parentWindow as any,
      'recordMessage',
      callback
    );

    expect(askForMediaPermissionSettingsMock).toHaveBeenCalledWith(
      'camera',
      parentWindow as any
    );
    expect(shellOpenExternalMock).toHaveBeenCalledWith(
      'ms-settings:privacy-webcam'
    );
    expect(callback).toHaveBeenCalledWith(false);
    expect(askForMediaAccessMock).not.toHaveBeenCalled();
  });

  it('allows permissions on Linux without checking Electron media statuses', async () => {
    setProcessPlatform('linux');

    const callback = jest.fn();

    await handleMediaPermissionRequest(
      ['audio', 'video'],
      null,
      'initiateCall',
      callback
    );

    expect(callback).toHaveBeenCalledWith(true);
    expect(getMediaAccessStatusMock).not.toHaveBeenCalled();
    expect(askForMediaAccessMock).not.toHaveBeenCalled();
    expect(askForMediaPermissionSettingsMock).not.toHaveBeenCalled();
  });

  it('falls back to permissive behavior on unsupported platforms', async () => {
    setProcessPlatform('freebsd');

    const callback = jest.fn();

    await handleMediaPermissionRequest(
      ['audio'],
      null,
      'initiateCall',
      callback
    );

    expect(callback).toHaveBeenCalledWith(true);
    expect(getMediaAccessStatusMock).not.toHaveBeenCalled();
  });
});

import { getAvailableBrowsers, launchBrowser } from 'detect-browsers';
import { shell } from 'electron';

import { dispatch } from '../../store';
import { readSetting } from '../../store/readSetting';
import { SETTINGS_AVAILABLE_BROWSERS_UPDATED } from '../../ui/actions';
import type * as BrowserLauncherModule from '../browserLauncher';

jest.mock('detect-browsers', () => ({
  getAvailableBrowsers: jest.fn(),
  launchBrowser: jest.fn(),
}));

jest.mock('electron', () => ({
  shell: {
    openExternal: jest.fn(),
  },
}));

jest.mock('../../store', () => ({
  dispatch: jest.fn(),
}));

jest.mock('../../store/readSetting', () => ({
  readSetting: jest.fn(),
}));

const mockGetAvailableBrowsers = getAvailableBrowsers as jest.Mock;
const mockLaunchBrowser = launchBrowser as jest.Mock;
const mockOpenExternal = shell.openExternal as jest.Mock;
const mockDispatch = dispatch as jest.Mock;
const mockReadSetting = readSetting as jest.Mock;

// browserLauncher caches state in module scope, so re-require it per test
// to exercise the lazy-load / promise-caching paths from a clean slate.
const loadModule = () => {
  let mod: typeof BrowserLauncherModule;
  jest.isolateModules(() => {
    mod = require('../browserLauncher');
  });
  return mod!;
};

const chromeBrowser = { browser: 'chrome', name: 'Google Chrome' } as any;
const firefoxBrowser = { browser: 'firefox', name: 'Firefox' } as any;

beforeEach(() => {
  jest.clearAllMocks();
  jest.useFakeTimers();
  mockOpenExternal.mockResolvedValue(undefined);
  mockLaunchBrowser.mockResolvedValue(undefined);
  jest.spyOn(console, 'error').mockImplementation(() => undefined);
  jest.spyOn(console, 'warn').mockImplementation(() => undefined);
});

afterEach(() => {
  jest.runOnlyPendingTimers();
  jest.useRealTimers();
  (console.error as jest.Mock).mockRestore();
  (console.warn as jest.Mock).mockRestore();
});

describe('openExternal', () => {
  it('uses system default when no browser is selected', async () => {
    mockReadSetting.mockReturnValue(undefined);
    const { openExternal } = loadModule();

    await openExternal('https://example.com');

    expect(mockOpenExternal).toHaveBeenCalledWith('https://example.com');
    expect(mockGetAvailableBrowsers).not.toHaveBeenCalled();
    expect(mockLaunchBrowser).not.toHaveBeenCalled();
  });

  it('lazy-loads browsers, dispatches the update and launches the selected browser', async () => {
    mockReadSetting.mockReturnValue('chrome');
    mockGetAvailableBrowsers.mockResolvedValue([chromeBrowser, firefoxBrowser]);
    const { openExternal } = loadModule();

    const promise = openExternal('https://example.com');
    // Advance past the 2s detection delay and flush the async detection.
    await jest.advanceTimersByTimeAsync(2000);
    await promise;

    expect(mockGetAvailableBrowsers).toHaveBeenCalledTimes(1);
    expect(mockDispatch).toHaveBeenCalledWith({
      type: SETTINGS_AVAILABLE_BROWSERS_UPDATED,
      payload: ['chrome', 'firefox'],
    });
    expect(mockLaunchBrowser).toHaveBeenCalledWith(
      chromeBrowser,
      'https://example.com'
    );
    expect(mockOpenExternal).not.toHaveBeenCalled();
  });

  it('reuses the cached browsers on subsequent calls (single detection)', async () => {
    mockReadSetting.mockReturnValue('chrome');
    mockGetAvailableBrowsers.mockResolvedValue([chromeBrowser]);
    const { openExternal } = loadModule();

    const first = openExternal('https://first.com');
    await jest.advanceTimersByTimeAsync(2000);
    await first;

    // Second call resolves from cache without scheduling a new detection.
    await openExternal('https://second.com');

    expect(mockGetAvailableBrowsers).toHaveBeenCalledTimes(1);
    expect(mockLaunchBrowser).toHaveBeenCalledTimes(2);
    expect(mockLaunchBrowser).toHaveBeenLastCalledWith(
      chromeBrowser,
      'https://second.com'
    );
  });

  it('does not dispatch when no browsers are detected', async () => {
    mockReadSetting.mockReturnValue('chrome');
    mockGetAvailableBrowsers.mockResolvedValue([]);
    const { openExternal } = loadModule();

    const promise = openExternal('https://example.com');
    await jest.advanceTimersByTimeAsync(2000);
    await promise;

    expect(mockDispatch).not.toHaveBeenCalled();
    // Selected browser not found -> falls back to system default.
    expect(mockOpenExternal).toHaveBeenCalledWith('https://example.com');
  });

  it('falls back to system default when the selected browser is unavailable', async () => {
    mockReadSetting.mockReturnValue('safari');
    mockGetAvailableBrowsers.mockResolvedValue([chromeBrowser]);
    const { openExternal } = loadModule();

    const promise = openExternal('https://example.com');
    await jest.advanceTimersByTimeAsync(2000);
    await promise;

    expect(mockLaunchBrowser).not.toHaveBeenCalled();
    expect(mockOpenExternal).toHaveBeenCalledWith('https://example.com');
  });

  it('falls back to system default and logs when detection rejects', async () => {
    mockReadSetting.mockReturnValue('chrome');
    mockGetAvailableBrowsers.mockRejectedValue(new Error('detect failed'));
    const { openExternal } = loadModule();

    const promise = openExternal('https://example.com');
    await jest.advanceTimersByTimeAsync(2000);
    await promise;

    // Detection error is caught inside the lazy loader (resolves []),
    // so the selected browser is simply not found -> system default.
    expect(mockLaunchBrowser).not.toHaveBeenCalled();
    expect(mockOpenExternal).toHaveBeenCalledWith('https://example.com');
    expect(console.error).toHaveBeenCalledWith(
      'Error detecting browsers:',
      expect.any(Error)
    );
  });

  it('propagates the rejection when launching the selected browser fails', async () => {
    // openExternal `return`s launchBrowser(...) directly (not awaited), so a
    // launch rejection escapes the try/catch and propagates to the caller.
    mockReadSetting.mockReturnValue('chrome');
    mockGetAvailableBrowsers.mockResolvedValue([chromeBrowser]);
    mockLaunchBrowser.mockRejectedValue(new Error('launch failed'));
    const { openExternal } = loadModule();

    const promise = openExternal('https://example.com');
    const assertion = expect(promise).rejects.toThrow('launch failed');
    await jest.advanceTimersByTimeAsync(2000);
    await assertion;

    expect(mockLaunchBrowser).toHaveBeenCalledWith(
      chromeBrowser,
      'https://example.com'
    );
    expect(mockOpenExternal).not.toHaveBeenCalled();
  });

  it('falls back to system default when launching the selected browser throws synchronously', async () => {
    mockReadSetting.mockReturnValue('chrome');
    mockGetAvailableBrowsers.mockResolvedValue([chromeBrowser]);
    mockLaunchBrowser.mockImplementation(() => {
      throw new Error('launch sync failed');
    });
    const { openExternal } = loadModule();

    const promise = openExternal('https://example.com');
    await jest.advanceTimersByTimeAsync(2000);
    await promise;

    expect(mockOpenExternal).toHaveBeenCalledWith('https://example.com');
    expect(console.error).toHaveBeenCalledWith(
      'Error launching browser:',
      expect.any(Error)
    );
  });
});

describe('preloadBrowsersList', () => {
  it('triggers browser detection in the background after its delay', async () => {
    mockGetAvailableBrowsers.mockResolvedValue([chromeBrowser]);
    const { preloadBrowsersList } = loadModule();

    preloadBrowsersList();
    expect(mockGetAvailableBrowsers).not.toHaveBeenCalled();

    // 5s outer delay, then the 2s detection delay inside the lazy loader.
    await jest.advanceTimersByTimeAsync(5000);
    await jest.advanceTimersByTimeAsync(2000);

    expect(mockGetAvailableBrowsers).toHaveBeenCalledTimes(1);
    expect(mockDispatch).toHaveBeenCalledWith({
      type: SETTINGS_AVAILABLE_BROWSERS_UPDATED,
      payload: ['chrome'],
    });
  });

  it('logs when the background preload rejects', async () => {
    // Force loadBrowsersLazy itself to reject by making setTimeout-bound
    // promise creation throw is not feasible; instead detection rejecting is
    // swallowed internally, so assert the preload completes without throwing.
    mockGetAvailableBrowsers.mockRejectedValue(new Error('boom'));
    const { preloadBrowsersList } = loadModule();

    preloadBrowsersList();
    await jest.advanceTimersByTimeAsync(5000);
    await jest.advanceTimersByTimeAsync(2000);

    expect(console.error).toHaveBeenCalledWith(
      'Error detecting browsers:',
      expect.any(Error)
    );
  });
});

